insert into public.cv_sections (key, data) values ('profile', '{"fullName":"Ștefan-Emanuel Ciupitu","headline":{"ro":"Inginer electronist · Masterand în Securitate Cibernetică","en":"Electronics Engineer · MSc Student in Cybersecurity"},"summary":{"ro":"Inginer electronist și masterand în Securitate Cibernetică, cu experiență în proiectare PCB, sisteme embedded, rețelistică și dezvoltare web. Certificat în 22 de cursuri de securitate cibernetică, inclusiv 16 cursuri Fortinet.","en":"Electronics engineer and MSc student in Cybersecurity, with hands-on experience in PCB design, embedded systems, networking and web development. Certified in 22 cybersecurity courses, including 16 Fortinet courses."},"about":{"ro":"Sunt o persoană pasionată de tehnologie, electronică și securitate cibernetică, mereu interesată să învăț lucruri noi și să îmi dezvolt competențele tehnice. Sunt inginer electronist și student la master în Securitate Cibernetică, cu experiență în proiectare hardware, dezvoltare software, rețelistică și sisteme embedded. Sunt o persoană curioasă, perseverentă, atentă la detalii și orientată spre găsirea soluțiilor, iar proiectele practice reprezintă pentru mine o modalitate importantă de a transforma cunoștințele teoretice în experiență reală.","en":"I am passionate about technology, electronics and cybersecurity, and always keen to learn and to keep growing my technical skills. I am an electronics engineer and an MSc student in Cybersecurity, with experience in hardware design, software development, networking and embedded systems. I am curious, persistent, detail-oriented and solution-focused, and I see hands-on projects as the best way to turn theoretical knowledge into real experience."},"valueProposition":{"ro":"Combin proiectarea hardware cu securitatea cibernetică: de la PCB-uri și optimizare SI/PI pentru interfețe de mare viteză, până la configurarea rețelelor și administrarea soluțiilor Fortinet. Lucrez practic, cu accent pe testare, validare și calitate.","en":"I bring hardware design and cybersecurity together: from PCBs and SI/PI optimisation for high-speed interfaces to network configuration and Fortinet administration. I work hands-on, with a strong focus on testing, validation and quality."},"location":{"ro":"Suceava, România","en":"Suceava, Romania"},"photoAlt":{"ro":"Portret profesional al lui Ștefan-Emanuel Ciupitu, în costum închis la culoare","en":"Professional portrait of Ștefan-Emanuel Ciupitu wearing a dark suit"},"focusAreas":[{"ro":"Proiectare PCB & interfețe de mare viteză","en":"PCB design & high-speed interfaces"},{"ro":"EMI/EMC & SI/PI","en":"EMI/EMC & SI/PI"},{"ro":"Securitate cibernetică & Fortinet","en":"Cybersecurity & Fortinet"},{"ro":"Firmware embedded & BLE","en":"Embedded firmware & BLE"},{"ro":"Rețelistică & fibră optică","en":"Networking & fibre optics"},{"ro":"Dezvoltare web (Next.js, React)","en":"Web development (Next.js, React)"}]}'::jsonb) on conflict (key) do nothing;
insert into public.cv_sections (key, data) values ('contact', '{"email":"ciupitustefan12@gmail.com","phone":"+40 773 735 023","showPhone":false,"showPhoneInPdf":false,"linkedin":"https://www.linkedin.com/in/ciupitu-stefan-emanuel/","github":"https://github.com/CiupituStefan","youtube":"https://www.youtube.com/@ciupitustefan","otherLinks":[]}'::jsonb) on conflict (key) do nothing;
insert into public.cv_sections (key, data) values ('experience', '[{"id":"aumovio-usv-research","kind":"research","organization":"AUMOVIO × USV","organizationUrl":"","role":{"ro":"Asistent de cercetare – masterand","en":"Research Assistant (MSc student)"},"location":{"ro":"Suceava, România","en":"Suceava, Romania"},"start":"2026-01","end":"2026-06","summary":{"ro":"Asigurarea implementării activităților de cercetare din cadrul unui proiect comun AUMOVIO și Universitatea „Ștefan cel Mare” din Suceava.","en":"Delivered research activities within a joint project between AUMOVIO and Ștefan cel Mare University of Suceava."},"responsibilities":[{"ro":"A1 – Ipoteze și modele conceptuale EMI/EMC pentru calificarea sistemelor integrate cu senzori și actuatoare în diverse configurații hardware.","en":"A1 – EMI/EMC hypotheses and conceptual models for qualifying integrated sensor and actuator systems across different hardware configurations."},{"ro":"A2 – Modele conceptuale și proceduri de optimizare SI/PI în proiectarea PCB și a interposerelor pentru interfețe de comunicații și circuite de mare viteză.","en":"A2 – Conceptual models and SI/PI optimisation procedures for PCB and interposer design for communication interfaces and high-speed circuits."},{"ro":"A3 – Formularea și verificarea ipotezelor, a modelelor conceptuale și a teoriilor privind comunicațiile prin interfețe de mare viteză.","en":"A3 – Formulating and verifying hypotheses, conceptual models and theories on communication over high-speed interfaces."}],"achievements":[{"ro":"Coordonarea resursei umane implicate în activitatea de verificare a modelelor pentru comunicații de mare viteză.","en":"Coordinated the team working on the verification of models for high-speed communications."}],"skills":["EMI/EMC","SI/PI","PCB Design","PCB Optimization","High-Speed Interfaces","Interposer Design","Hardware Design","System Qualification","Conceptual Modeling","Research","Data Analysis","Hypothesis Testing","Team Coordination","Project Management"]},{"id":"usv-fortinet-practicum","kind":"internship","organization":"Universitatea „Ștefan cel Mare” din Suceava","organizationUrl":"","role":{"ro":"Student practicant – Administrare soluții Fortinet","en":"Student Intern – Fortinet Solutions Administration"},"location":{"ro":"Suceava, România","en":"Suceava, Romania"},"start":"2026-02","end":"2026-05","summary":{"ro":"Cursuri teoretice și practice de securitate cibernetică și administrare a soluțiilor Fortinet, în cadrul programului universitar de practică.","en":"Theoretical and hands-on courses in cybersecurity and Fortinet solutions administration, as part of the university practicum programme."},"responsibilities":[{"ro":"Dezvoltarea competențelor de administrare FortiGate, FortiManager, FortiAnalyzer, FortiMail, FortiNAC, FortiSIEM, FortiSwitch și FortiWeb.","en":"Built administration skills across FortiGate, FortiManager, FortiAnalyzer, FortiMail, FortiNAC, FortiSIEM, FortiSwitch and FortiWeb."}],"achievements":[{"ro":"Finalizarea a 16 cursuri de specialitate Fortinet, cu obținerea certificatelor aferente.","en":"Completed 16 specialised Fortinet courses and earned the corresponding certificates."}],"skills":["FortiGate","FortiManager","FortiAnalyzer","FortiMail","FortiNAC","FortiSIEM","FortiSwitch","FortiWeb","FortiOS","Network Security"]},{"id":"usv-cyber-practicum","kind":"internship","organization":"Universitatea „Ștefan cel Mare” din Suceava","organizationUrl":"","role":{"ro":"Student practicant – Securitate cibernetică","en":"Student Intern – Cybersecurity"},"location":{"ro":"Suceava, România","en":"Suceava, Romania"},"start":"2025-10","end":"2026-02","summary":{"ro":"Cursuri teoretice și practice în domeniul securității cibernetice, puse la dispoziție în cadrul programului universitar.","en":"Theoretical and hands-on cybersecurity courses provided through the university programme."},"responsibilities":[{"ro":"Dezvoltarea competențelor în Cyber Threat Management, Endpoint Security, Network Defense și Ethical Hacking.","en":"Developed skills in Cyber Threat Management, Endpoint Security, Network Defense and Ethical Hacking."}],"achievements":[{"ro":"Finalizarea a 6 cursuri, însumând 176 de ore, cu obținerea certificatelor aferente.","en":"Completed 6 courses totalling 176 hours and earned the corresponding certificates."}],"skills":["Cyber Threat Management","Endpoint Security","Network Defense","Ethical Hacking"]},{"id":"daily-caffe","kind":"work","organization":"Daily Caffe","organizationUrl":"https://www.dailycaffe.ro/","role":{"ro":"Inginer electronist","en":"Electronics Engineer"},"location":{"ro":"Suceava, România","en":"Suceava, Romania"},"start":"2025-07","end":"2025-10","summary":{"ro":"Supervizarea procesului end-to-end de recondiționare și implementare a automatelor de cafea, de la diagnoza hardware inițială până la validarea finală pentru livrare.","en":"Oversaw the end-to-end refurbishment and deployment of coffee vending machines, from initial hardware diagnostics to final validation before delivery."},"responsibilities":[{"ro":"Integrare hardware și mentenanță avansată: diagnoză și reparații la nivel de componentă pentru subansamble critice (cititoare de bancnote, pompe, boilere).","en":"Hardware integration and advanced maintenance: component-level diagnostics and repair of critical sub-assemblies (banknote readers, pumps, boilers)."},{"ro":"Integrarea completă a soluțiilor de plată (jetoniere, POS), inclusiv realizarea de cabluri custom.","en":"End-to-end integration of payment systems (coin mechanisms, POS terminals), including building custom cables."},{"ro":"Deployment și configurare software: instalarea sistemelor de operare și flash-uirea firmware-ului, cu scripturi de configurare pe USB pentru setarea eficientă a parametrilor operaționali (ex.: prețuri).","en":"Software deployment and configuration: operating-system installation and firmware flashing, with USB configuration scripts for efficient set-up of operating parameters (e.g. prices)."}],"achievements":[{"ro":"Asigurarea calității: teste de validare finală care certifică funcționalitatea completă a echipamentelor — sisteme mecanice, termice și de plată.","en":"Quality assurance: ran final validation tests certifying full equipment functionality — mechanical, thermal and payment systems."}],"skills":["Hardware Diagnostics","Component-level Repair","Hardware Integration","Custom Cabling","Software Deployment","Firmware Flashing","Scripting","Payment Systems / POS","Quality Assurance","System Testing"]},{"id":"usv-bachelor-thesis","kind":"project","organization":"Universitatea „Ștefan cel Mare” din Suceava","organizationUrl":"","role":{"ro":"Lucrare de diplomă – Tastatură wireless BLE","en":"Bachelor''s thesis – BLE wireless keyboard"},"location":{"ro":"Suceava, România","en":"Suceava, Romania"},"start":"2025-06","end":"2025-07","summary":{"ro":"Proiectarea și realizarea completă a unei tastaturi wireless cu consum redus de energie: hardware, firmware, carcasă și alimentare.","en":"End-to-end design and build of a low-power wireless keyboard: hardware, firmware, enclosure and power supply."},"responsibilities":[{"ro":"Management de proiect: dezvoltare cu metodologie Agile, iterativă și flexibilă, pe tot parcursul designului și implementării.","en":"Project management: iterative, flexible Agile approach throughout design and implementation."},{"ro":"Dezvoltare firmware: firmware custom pe platforma ZMK, specializată pentru dispozitive wireless Bluetooth Low Energy (BLE).","en":"Firmware development: custom firmware built on ZMK, a platform specialised for Bluetooth Low Energy (BLE) wireless devices."},{"ro":"Proiectare hardware: arhitectura hardware și circuitul imprimat (PCB) în Altium, optimizate pentru conectivitate BLE.","en":"Hardware design: hardware architecture and printed circuit board (PCB) in Altium, optimised for BLE connectivity."},{"ro":"Design mecanic: carcasă modelată 3D în Fusion 360, cu design ergonomic și estetic.","en":"Mechanical design: ergonomic, aesthetic enclosure modelled in 3D in Fusion 360."}],"achievements":[{"ro":"Sistem de alimentare pe baterie implementat și optimizat, proiectat pentru o autonomie de până la un an.","en":"Implemented and optimised a battery power system designed for up to one year of autonomy."}],"skills":["Altium","Fusion 360","Bluetooth Low Energy","ZMK","C","Agile","3D Modeling","Power Management","Git","EMC"]},{"id":"netcom-activ","kind":"internship","organization":"NETCOM ACTIV","organizationUrl":"https://netcom-activ.ro/","role":{"ro":"Intern – rețele și fibră optică","en":"Intern – Networks & Fibre Optics"},"location":{"ro":"Suceava, România","en":"Suceava, Romania"},"start":"2025-03","end":"2025-05","summary":{"ro":"","en":""},"responsibilities":[{"ro":"Implementare și mentenanță infrastructuri de fibră optică: joncțiuni prin sudură de înaltă precizie (fusion splicing), cu atenuare minimă a semnalului.","en":"Fibre-optic infrastructure deployment and maintenance: high-precision fusion splicing with minimal signal attenuation."},{"ro":"Configurare echipamente de rețea (CPE): punerea în funcțiune la client, cu configurarea avansată a routerelor și switch-urilor pentru conexiuni de date sigure, conform parametrilor tehnici ai proiectului.","en":"Network equipment (CPE) configuration: on-site commissioning, including advanced router and switch configuration to establish and secure data connections according to project specifications."},{"ro":"Cablare structurată UTP/FTP: pozarea cablurilor și sertizarea conectorilor RJ45 conform standardelor, pentru rețele locale (LAN) fiabile.","en":"Structured UTP/FTP cabling: cable routing and RJ45 termination to standard, building reliable local area networks (LAN)."}],"achievements":[{"ro":"Validarea fiecărei etape a instalării, de la conectivitatea fizică la configurarea logică a rețelei.","en":"Validated every installation stage, from physical connectivity to logical network configuration."}],"skills":["Fusion Splicing","Fiber Optics","Router Configuration","Switch Configuration","CPE","Structured Cabling","UTP/FTP","RJ45","LAN"]},{"id":"sunday-river","kind":"exchange","organization":"Sunday River","organizationUrl":"https://www.sundayriver.com/","role":{"ro":"Participant Work and Travel USA","en":"Work and Travel USA participant"},"location":{"ro":"Newry, Maine, SUA","en":"Newry, Maine, USA"},"start":"2024-06","end":"2024-09","summary":{"ro":"Program de schimb cultural și profesional, într-un mediu hotelier internațional și dinamic.","en":"Cultural and professional exchange programme in a dynamic, international hospitality environment."},"responsibilities":[{"ro":"Comunicare zilnică în limba engleză cu o clientelă și o echipă diverse din punct de vedere cultural.","en":"Daily communication in English with culturally diverse guests and colleagues."}],"achievements":[{"ro":"Dezvoltarea competențelor de comunicare în limba engleză (nivel B2), multitasking, management al timpului și atenție la detalii.","en":"Strengthened English communication (B2), multitasking, time management and attention to detail."}],"skills":["English Communication","Cross-cultural Communication","Multitasking","Time Management","Adaptability"]},{"id":"gmv-design","kind":"internship","organization":"GMV Design","organizationUrl":"https://gmv.design/","role":{"ro":"Intern – dezvoltare web","en":"Web Development Intern"},"location":{"ro":"Suceava, România","en":"Suceava, Romania"},"start":"2024-03","end":"2024-05","summary":{"ro":"Reconstruirea integrală a site-ului gmv.design cu un stack tehnologic modern, pentru performanță și o experiență de utilizare superioară.","en":"Rebuilt the gmv.design website from the ground up on a modern stack, for better performance and user experience."},"responsibilities":[{"ro":"Implementarea arhitecturii front-end.","en":"Implemented the front-end architecture."},{"ro":"Gestionarea părții de backend și a managementului API-urilor.","en":"Handled the back end and API management."}],"achievements":[{"ro":"Aplicarea tehnicilor de optimizare a performanței și SEO on-page pentru o experiență rapidă și eficientă.","en":"Applied performance optimisation and on-page SEO techniques for a fast, efficient experience."}],"skills":["Next.js","React","Tailwind CSS","HTML/CSS","Node.js","MySQL","Git","Figma","Cypress"]},{"id":"aerostar","kind":"internship","organization":"Aerostar S.A.","organizationUrl":"https://www.aerostar.ro/","role":{"ro":"Intern – inginerie electronică","en":"Electronics Engineering Intern"},"location":{"ro":"Bacău, România","en":"Bacău, Romania"},"start":"2023-08","end":"2023-09","summary":{"ro":"","en":""},"responsibilities":[{"ro":"Participare activă la procesele de testare și certificare pentru sisteme de radar secundar destinate produselor militare, conform standardelor de calitate din industria de apărare.","en":"Took an active part in testing and certification of secondary radar systems for military products, in line with defence-industry quality standards."},{"ro":"Proiectarea de circuite imprimate (PCB) pentru aplicații specializate, în OrCAD.","en":"Designed printed circuit boards (PCBs) for specialised applications in OrCAD."},{"ro":"Contribuție la procesul de fabricație a cablajelor de uz militar, în contextul industriei aerospațiale și de apărare.","en":"Contributed to manufacturing military-grade cable harnesses within the aerospace and defence industry."}],"achievements":[],"skills":["OrCAD","PCB Design","Radar Systems","EMC","Military Standards","Cable Manufacturing","System Testing","Certification"]}]'::jsonb) on conflict (key) do nothing;
