insert into public.projects (slug, status, featured, sort_order, category, year, title, summary, description, objective, problem, role, contribution, process, results, technologies, live_url, repo_url, docs_url) values ('ble-wireless-keyboard', 'published', true, 10, 'embedded', 2025, '{"ro":"Tastatură wireless BLE – lucrare de diplomă","en":"BLE wireless keyboard – bachelor''s thesis"}'::jsonb, '{"ro":"Tastatură wireless cu consum redus de energie, realizată complet: PCB în Altium, firmware ZMK, carcasă 3D în Fusion 360 și alimentare pe baterie proiectată pentru până la un an de autonomie.","en":"A low-power wireless keyboard built end to end: Altium PCB, ZMK firmware, a Fusion 360 3D-modelled enclosure and a battery system designed for up to one year of autonomy."}'::jsonb, '{"ro":"","en":""}'::jsonb, '{"ro":"Proiectarea și realizarea unei tastaturi wireless Bluetooth Low Energy, cu autonomie îndelungată, ca lucrare de diplomă la Universitatea „Ștefan cel Mare” din Suceava.","en":"Design and build a Bluetooth Low Energy wireless keyboard with long battery life, as my bachelor''s thesis at Ștefan cel Mare University of Suceava."}'::jsonb, '{"ro":"","en":""}'::jsonb, '{"ro":"Autor – proiectare hardware, firmware și mecanică","en":"Author – hardware, firmware and mechanical design"}'::jsonb, '{"ro":"Am proiectat arhitectura hardware și PCB-ul în Altium, optimizate pentru conectivitate BLE; am dezvoltat firmware-ul custom pe platforma ZMK; am modelat 3D carcasa în Fusion 360, cu un design ergonomic și estetic; am implementat și optimizat sistemul de alimentare pe baterie.","en":"I designed the hardware architecture and the PCB in Altium, optimised for BLE connectivity; developed the custom firmware on ZMK; modelled an ergonomic, aesthetic enclosure in Fusion 360; and implemented and optimised the battery power system."}'::jsonb, '{"ro":"Dezvoltare iterativă, după o metodologie Agile, cu o abordare flexibilă pe parcursul etapelor de design și implementare.","en":"Iterative development following an Agile methodology, keeping the design and implementation phases flexible."}'::jsonb, '{"ro":"Sistem de alimentare pe baterie proiectat pentru o autonomie de până la un an.","en":"Battery power system designed for up to one year of autonomy."}'::jsonb, array['Altium Designer', 'ZMK', 'C', 'Bluetooth Low Energy', 'Fusion 360', 'Power Management', 'Git', 'EMC', 'Agile']::text[], '', '', '') on conflict (slug) do nothing;
insert into public.projects (slug, status, featured, sort_order, category, year, title, summary, description, objective, problem, role, contribution, process, results, technologies, live_url, repo_url, docs_url) values ('rfid-antenna-13-56-mhz', 'published', true, 20, 'rf', 2024, '{"ro":"Antenă RFID pentru 13,56 MHz","en":"13.56 MHz RFID antenna"}'::jsonb, '{"ro":"Proiectarea, simularea și realizarea unei antene RFID în ANSYS, cu calculul inductanței, analiza impedanței pe diagrama Smith și validare prin teste în condiții reale.","en":"Design, simulation and build of an RFID antenna in ANSYS, including inductance calculation, Smith-chart impedance analysis and real-world validation."}'::jsonb, '{"ro":"","en":""}'::jsonb, '{"ro":"Proiectarea, simularea și realizarea unei antene RFID funcționale pentru frecvența de 13,56 MHz.","en":"Design, simulate and build a working RFID antenna for 13.56 MHz."}'::jsonb, '{"ro":"","en":""}'::jsonb, '{"ro":"","en":""}'::jsonb, '{"ro":"","en":""}'::jsonb, '{"ro":"Proiectare și simulare în ANSYS, inclusiv calculul inductanței și analiza impedanței prin diagrama Smith. Performanța antenei a fost optimizată prin adăugarea unui strat suplimentar de carton, pentru îmbunătățirea câștigului și a eficienței radiației.","en":"Designed and simulated in ANSYS, including inductance calculation and impedance analysis on the Smith chart. Antenna performance was optimised by adding an extra cardboard layer to improve gain and radiation efficiency."}'::jsonb, '{"ro":"Proiect validat prin teste de performanță în condiții reale.","en":"Validated through performance tests in real-world conditions."}'::jsonb, array['Ansys HFSS', 'RF Design', 'Smith Chart', 'Impedance Matching']::text[], '', '', '') on conflict (slug) do nothing;
insert into public.projects (slug, status, featured, sort_order, category, year, title, summary, description, objective, problem, role, contribution, process, results, technologies, live_url, repo_url, docs_url) values ('gmv-design-website', 'published', true, 30, 'web', 2024, '{"ro":"Reconstruirea site-ului gmv.design","en":"gmv.design website rebuild"}'::jsonb, '{"ro":"Reconstruirea integrală a site-ului gmv.design în cadrul internship-ului la GMV Design, cu un stack modern, optimizare de performanță și SEO on-page.","en":"Complete rebuild of the gmv.design website during my internship at GMV Design, on a modern stack with performance optimisation and on-page SEO."}'::jsonb, '{"ro":"","en":""}'::jsonb, '{"ro":"Un site modern, rapid și ușor de utilizat, care să ofere o experiență superioară vizitatorilor.","en":"A modern, fast and easy-to-use website delivering a better experience for visitors."}'::jsonb, '{"ro":"","en":""}'::jsonb, '{"ro":"Intern – dezvoltare web","en":"Web development intern"}'::jsonb, '{"ro":"Am implementat arhitectura front-end, am gestionat partea de backend și managementul API-urilor și am aplicat tehnici de optimizare a performanței și SEO on-page.","en":"I implemented the front-end architecture, handled the back end and API management, and applied performance optimisation and on-page SEO techniques."}'::jsonb, '{"ro":"","en":""}'::jsonb, '{"ro":"","en":""}'::jsonb, array['Next.js', 'React', 'Tailwind CSS', 'Node.js', 'MySQL', 'Figma', 'Cypress', 'Git']::text[], 'https://gmv.design/', '', '') on conflict (slug) do nothing;
