insert into public.projects (slug, status, featured, sort_order, category, year, title, summary, description, objective, problem, role, contribution, process, results, technologies, live_url, repo_url, docs_url) values ('arduino-conveyor-counter', 'published', false, 120, 'embedded', 2023, '{"ro":"Numărarea obiectelor pe o bandă transportoare","en":"Conveyor-belt object counter"}'::jsonb, '{"ro":"Sistem bazat pe Arduino care numără obiectele de pe o bandă transportoare cu un senzor infraroșu și afișează rezultatul pe un display OLED.","en":"An Arduino-based system that counts objects on a conveyor belt with an infrared sensor and shows the count on an OLED display."}'::jsonb, '{"ro":"","en":""}'::jsonb, '{"ro":"","en":""}'::jsonb, '{"ro":"","en":""}'::jsonb, '{"ro":"","en":""}'::jsonb, '{"ro":"","en":""}'::jsonb, '{"ro":"Sistemul folosește un Arduino, un display OLED, un buzzer și un senzor infraroșu: la fiecare trecere prin fața senzorului, un obiect este numărat și afișat pe display.","en":"The system uses an Arduino, an OLED display, a buzzer and an infrared sensor: each pass in front of the sensor counts one object and shows the total on the display."}'::jsonb, '{"ro":"","en":""}'::jsonb, array['Arduino', 'C/C++', 'IR Sensor', 'OLED Display']::text[], '', '', '') on conflict (slug) do nothing;
